import { createStore } from "redux";

const initialState = {
  fullName: "",
  nationalID: "",
  createdAt: "",
};

function reducer(state = initialState, action) {
  switch (action.type) {
    case "customer/createCustomer":
      return {
        ...state,
        fullName: action.payloud.fullName,
        nationalID: action.payloud.nationalID,
        createdAt: action.payloud.createdAt,
      };
    case "customer/updateName":
      return { ...state, fullName: action.payloud.fullName };

    default:
      throw new Error(`${action.type}Unknown account reducer type was made`);
  }
}

function createCustomer(fullName, nationalID) {
  const now = new Date();
  return {
    type: "customer/createCustomer",
    payloud: { fullName, nationalID, createdAt: now.toString() },
  };
}

function updateCustomer(fullName) {
  return { type: "customer/updateName", payloud: fullName };
}

const store = createStore({ reducer });

export { store, createCustomer, updateCustomer };
